// Example TEAMS for the Saved teams library. Each is a team definition (an org tree of agents
// with roles, models, caps, communication edges and rules plus a project profile), never a
// project: inserting one creates a new team and makes it active, without a goal, workspace,
// workflow or task. Projects are assigned to the team afterwards (src/projects.ts).
//
// - Plan → implement → review pipeline team: generated by src/pipeline.ts (worker caps, model
//   mappings and the Codex effort are configured at insert).
// - Wolfram-validated reasoning team: generated by src/samples.ts (one or two validators).
// - Product feature team: the bundled template assets/example-teams/product-feature-team.json.
//
// Model verification runs at insert (blocking unless `acceptUnverifiedModels` is explicit) and
// again for every project before it can resume.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { z } from "zod";
import { projectRoot } from "./config.ts";
import type { DetectedRuntime } from "./discovery.ts";
import { AppError, assert } from "./model.ts";
import {
  DEFAULT_CODEX_EFFORT,
  DEFAULT_MODELS,
  MAX_WORKERS,
  pipelineTeamTemplate,
} from "./pipeline.ts";
import {
  assessModels,
  wolframTeamTemplate,
  type ModelCheck,
} from "./samples.ts";
import type { TeamService } from "./service.ts";
import { PROJECT_TYPE_LABEL, type TeamProfile } from "./team-profiles.ts";
import {
  TeamTemplates,
  checkCompatibility,
  teamTemplateSchema,
  type TeamTemplate,
} from "./teams.ts";

export type ExampleField =
  | {
      key: string;
      label: string;
      kind: "count";
      min: number;
      max: number;
      default: number;
    }
  | { key: string; label: string; kind: "text"; default: string };

type Example = {
  id: string;
  /** One line: the team shape (lead + roles). */
  shape: string;
  fields: ExampleField[];
  build: (options: Record<string, unknown>) => TeamTemplate;
};

const text = (key: string, label: string, value: string): ExampleField => ({
  key,
  label,
  kind: "text",
  default: value,
});

let productCache: TeamTemplate | undefined;
/** The bundled product feature team (read once; validated like any imported template). */
export function productFeatureTemplate(): TeamTemplate {
  productCache ??= checkCompatibility(
    JSON.parse(
      readFileSync(
        join(
          projectRoot,
          "assets",
          "example-teams",
          "product-feature-team.json",
        ),
        "utf8",
      ),
    ),
  );
  return structuredClone(productCache);
}

