const optionsSchema = z
  .record(z.string().max(40), z.union([z.string().max(200), z.number()]))
  .default({});

function find(id: string) {
  const e = EXAMPLES.find((x) => x.id === id);
  if (!e) throw new AppError(404, "not_found", `No example team ${id}`);
  return e;
}
/** Defaults filled in, counts as integers inside their bounds, text trimmed (empty = default). */
function options(e: Example, input: unknown) {
  const raw = optionsSchema.parse(input);
  for (const k of Object.keys(raw))
    assert(
      e.fields.some((f) => f.key === k),
      "unknown_option",
      `Unknown option ${k} for this example team`,
      400,
    );
  return Object.fromEntries(
    e.fields.map((f) => {
      const v = raw[f.key];
      if (f.kind === "count") {
        const n = v === undefined ? f.default : Number(v);
        assert(
          Number.isInteger(n) && n >= f.min && n <= f.max,
          "invalid_option",
          `${f.label} must be a whole number from ${f.min} to ${f.max}`,
          400,
        );
        return [f.key, n];
      }
      const s = v === undefined ? "" : String(v).trim();
      return [f.key, s || f.default];
    }),
  );
}

/** Insert-time model check of a template (keys stand in for agent ids). */
export function checkTemplateModels(
  t: TeamTemplate,
  runtimes: DetectedRuntime[] | undefined,
): ModelCheck {
  const r = assessModels(
    t.agents.map((a) => ({
      id: a.key,
      name: a.name,
      environment: a.environment,
      model: a.model,
      effort: a.effort,
    })),
    runtimes,
    {
      ...(t.project?.intendedLead
        ? { leadId: t.project.lead, intendedLead: t.project.intendedLead }
        : {}),
      expectations: t.project?.expectations ?? {},
    },
  );
  return {
    verified: !r.issues.length,
    checkedAt: new Date().toISOString(),
    ...r,
  };
}

const insertSchema = z
  .object({
    options: optionsSchema,
    teamName: z.string().trim().min(1).max(80).optional(),
    /** Insert although the model check did not pass; projects still verify before resuming. */
    acceptUnverifiedModels: z.boolean().default(false),
  })
  .strict();

export class ExampleTeams {
  service: TeamService;
  teams: TeamTemplates;
  runtimes: () => DetectedRuntime[] | undefined;
  constructor(
    service: TeamService,
    teams: TeamTemplates,
    runtimes: () => DetectedRuntime[] | undefined,
  ) {
    this.service = service;
    this.teams = teams;
    this.runtimes = runtimes;
  }
  list() {
    return EXAMPLES.map((e) => {
      const template = e.build(options(e, {}));
      const type = template.project?.type ?? "free-form";
      return {
        id: e.id,
        name: template.name,
        shape: e.shape,
        description: template.description,
        projectType: type,
        projectLabel: PROJECT_TYPE_LABEL[type],
        fields: e.fields,
        template,
      };
    });
  }
  /** The configured template, its model check and the structural insert preview; no writes. */
  async preview(id: string, input: unknown) {
    const e = find(id);
    const body = z
      .object({ options: optionsSchema })
      .strict()
      .parse(input ?? {});
    const template = e.build(options(e, body.options));
    const modelCheck = checkTemplateModels(template, this.runtimes());
    // Environment/model availability is reported by the model check above.
    const preview = await this.teams.preview({
      envelope: {
        format: "agentteam.team-template",
        schemaVersion: 3,
        template,
      },
      allowUnknownModels: true,
      allowUninstalledEnvironments: true,
    });
    return { template, modelCheck, preview };
  }
  /** Insert the example as a new, active team with its project profile; creates no project. */
  insert(id: string, input: unknown) {
    const e = find(id);
    const body = insertSchema.parse(input ?? {});
    const template = e.build(options(e, body.options));
    const modelCheck = checkTemplateModels(template, this.runtimes());
    if (!modelCheck.verified && !body.acceptUnverifiedModels)
      throw new AppError(
        409,
        "models_unverified",
        `Model verification did not pass: ${modelCheck.issues.join("; ")}. Fix the model mapping or insert explicitly unverified (projects stay blocked until their models verify).`,
      );
    const result = this.teams.insertTemplate(
      template,
      {
        ...(body.teamName ? { teamName: body.teamName } : {}),
        allowUnknownModels: true,
        allowUninstalledEnvironments: true,
      },
      (r) => {
        if (!r.profile) return;
        const profile: TeamProfile = {
          ...r.profile,
          source: { template: template.name, example: e.id },
          modelCheck: {
            ...modelCheck,
            // Keys -> the inserted agents' ids.
            resolved: modelCheck.resolved.map((x) => ({
              ...x,
              agentId: r.idMap[x.agentId] ?? x.agentId,
            })),
          },
        };
        this.service.store.put("team-profile", profile);
        r.profile = profile;
      },
    );
    return { ...result, modelCheck, example: e.id };
  }
}
